// numValidators mirrors circuit/reanchoring/src/main.nr's NUM_VALIDATORS:
// genesis-fixed, hardcoded (CLAUDE.md: "no staking-driven rotation"). A
// deployment with a different validator count needs a recompiled circuit
// (and a matching change here), not a runtime parameter.
const numValidators = 7

// buildBoundaryWitnessCmd queries this node's real boundary-block binding
// data (x/sovereignty/keeper/grpc_query.go's RecoveryHeaders, extended this
// pass) and the real per-validator ed25519 precommit signatures for the
// interval's two boundary heights (via CometBFT's real /commit RPC), and
// writes a Prover.toml fragment for circuit/reanchoring/src/main.nr's
// ValidatorSetWitness/BoundaryBlockWitness parameters -- the counterpart of
// query-recovery-headers/prove_and_submit.sh's existing header-chain
// witness, for the NEW boundary-signature-binding half of the circuit
// (circuit/README.md's Scope section).
func buildBoundaryWitnessCmd() *cobra.Command {
	var nodeURL, chainID, outFile string
	var lastHeight uint64
	cmd := &cobra.Command{
		Use:   "build-boundary-witness",
		Short: "Build the boundary-block Prover.toml fragment for the ZK re-anchoring circuit's boundary-signature binding",
		RunE: func(cmd *cobra.Command, args []string) error {
			client, err := rpchttp.New(nodeURL, "/websocket")
			if err != nil {
				return err
			}
			ctx := context.Background()

			reqBytes, err := proto.Marshal(&sovereigntytypes.QueryRecoveryHeadersRequest{})
			if err != nil {
				return err
			}
			resp, err := client.ABCIQuery(ctx, "/engram.sovereignty.v1.Query/RecoveryHeaders", reqBytes)
			if err != nil {
				return err
			}
			if resp.Response.Code != 0 {
				return fmt.Errorf("query failed: %s", resp.Response.Log)
			}
			var q sovereigntytypes.QueryRecoveryHeadersResponse
			if err := proto.Unmarshal(resp.Response.Value, &q); err != nil {
				return err
			}

			if len(q.Validators) != numValidators {
				return fmt.Errorf(
					"expected %d genesis validators (circuit/reanchoring/src/main.nr's NUM_VALIDATORS is hardcoded), chain has %d -- recompile the circuit (and this tool) if this deployment's validator count differs",
					numValidators, len(q.Validators))
			}
			// first_height is LastAnchoredHeight+1 (headers[0]'s OWN height,
			// the interval's first real WithdrawLocked block) -- msg_server.go's
			// SubmitRecoveryProof doc explains why LastAnchoredHeight itself
			// (the pre-interval ANCHORED block) never gets a BlockHashByHeight
			// entry.
			firstHeight := uint64(q.LastAnchoredHeight) + 1
			firstBlockHash, ok := q.BlockHashes[firstHeight]
			if !ok {
				return fmt.Errorf("no tracked block hash for first_height=%d yet (BlockHashByHeight not populated -- interval may not have started, or hasn't been recorded yet)", firstHeight)
			}

			// last_height defaults to the highest height BlockHashByHeight
			// already has real data for (any tracked height can be a rolling
			// checkpoint -- keeper.go's BlockHashByHeight doc, replacing an
			// earlier design that required proving the WHOLE interval in one
			// shot and deadlocked as a result). --last-height overrides this
			// for building a proof to an earlier checkpoint deliberately.
			target := lastHeight
			if target == 0 {
				for h := range q.BlockHashes {
					if h != firstHeight && h > target {
						target = h
					}
				}
				if target == 0 {
					return fmt.Errorf("no candidate last_height available yet: BlockHashByHeight only has an entry for first_height=%d so far -- wait for at least one more block while the interval is active, or pass --last-height explicitly", firstHeight)
				}
			}
			lastBlockHash, ok := q.BlockHashes[target]
			if !ok {
				return fmt.Errorf("no tracked block hash for --last-height=%d (available heights: %v)", target, blockHashKeys(q.BlockHashes))
			}

			firstBlock, err := buildBoundaryBlockWitness(ctx, client, firstHeight, chainID, q.Validators, "first_block")
			if err != nil {
				return fmt.Errorf("first boundary (height %d): %w", firstHeight, err)
			}
			lastBlock, err := buildBoundaryBlockWitness(ctx, client, target, chainID, q.Validators, "last_block")
			if err != nil {
				return fmt.Errorf("last boundary (height %d): %w", target, err)
			}

			validatorsToml, err := buildValidatorSetToml(q.Validators)
			if err != nil {
				return fmt.Errorf("validator set: %w", err)
			}

			out, err := os.Create(outFile)
			if err != nil {
				return err
			}
			defer out.Close()

			fmt.Fprintf(out, "first_height = \"%d\"\n", firstHeight)
			fmt.Fprintf(out, "first_block_hash = \"%s\"\n", fieldDecimal(sovereigntytypes.ReduceToField(firstBlockHash)))
			fmt.Fprintf(out, "last_block_hash = \"%s\"\n", fieldDecimal(sovereigntytypes.ReduceToField(lastBlockHash)))
			fmt.Fprintf(out, "validator_set_hash = \"%s\"\n", fieldDecimal(sovereigntytypes.ReduceToField(q.ValidatorSetHash)))
			fmt.Fprintf(out, "first_block_hash_bytes = [%s]\n", byteArrayToml(firstBlockHash))
			fmt.Fprintf(out, "last_block_hash_bytes = [%s]\n", byteArrayToml(lastBlockHash))
			fmt.Fprintf(out, "validator_set_hash_bytes = [%s]\n", byteArrayToml(q.ValidatorSetHash))
			fmt.Fprint(out, "\n[validators]\n")
			fmt.Fprint(out, validatorsToml)
			fmt.Fprint(out, "\n[first_block]\n")
			fmt.Fprint(out, firstBlock)
			fmt.Fprint(out, "\n[last_block]\n")
			fmt.Fprint(out, lastBlock)

			fmt.Printf("boundary witness written to %s (first_height=%d last_height=%d)\n", outFile, firstHeight, target)
			return nil
		},
	}
	cmd.Flags().StringVar(&nodeURL, "node", "http://127.0.0.1:26657", "CometBFT RPC endpoint")
	cmd.Flags().StringVar(&chainID, "chain-id", "engram-dev-1", "chain ID -- must match circuit/reanchoring/src/main.nr's CHAIN_ID constant exactly")
	cmd.Flags().StringVar(&outFile, "out", "", "path to write the Prover.toml fragment (required)")
	cmd.Flags().Uint64Var(&lastHeight, "last-height", 0, "checkpoint height to prove up to (default: the highest height BlockHashByHeight already has data for)")
	_ = cmd.MarkFlagRequired("out")
	return cmd
}

func blockHashKeys(m map[uint64][]byte) []uint64 {
	keys := make([]uint64, 0, len(m))
	for h := range m {
		keys = append(keys, h)
	}
	return keys
}

// buildBoundaryBlockWitness fetches the real commit at height via CometBFT's
// /commit RPC and builds a BoundaryBlockWitness TOML fragment (the [tableName]
// header itself is written by the caller; only nested sub-tables, like
// timestamp_content's, are emitted here with the full dotted path).
func buildBoundaryBlockWitness(ctx context.Context, client *rpchttp.HTTP, height uint64, chainID string, validators []*sovereigntytypes.QueryValidatorInfo, tableName string) (string, error) {
	h := int64(height)
	commitResult, err := client.Commit(ctx, &h)
	if err != nil {
		return "", fmt.Errorf("fetching commit: %w", err)
	}
	commit := commitResult.Commit
	if commit == nil {
		return "", fmt.Errorf("commit is nil at height %d", height)
	}
	// build_vote_sign_bytes (circuit/reanchoring/src/main.nr) only supports
	// round==0 precommits (proto3 elides the round field from the wire
	// bytes when it's zero -- a documented circuit scope limit, not a
	// silent gap). A real round-skip at either boundary height makes this
	// tool unable to build a witness for it at all.
	if commit.Round != 0 {
		return "", fmt.Errorf(
			"commit.Round=%d at height %d, but the circuit only supports round==0 precommits "+
				"(build_vote_sign_bytes's doc) -- cannot build a witness for this height",
			commit.Round, height)
	}
	if len(commit.Signatures) != numValidators {
		return "", fmt.Errorf("commit has %d signatures, expected %d", len(commit.Signatures), numValidators)
	}

	var (
		sigRXs, sigRYs, sigSs                          [numValidators][]byte
		tsContentBytes                                 [numValidators][]byte
		signed                                         [numValidators]bool
		dummySigRX, dummySigRY, dummySigS, dummyTsBytes []byte
		haveDummy                                      bool
		ps_total                                       uint32
		psHashBytes                                    []byte
	)

	for i := 0; i < numValidators; i++ {
		pub := cmted25519.PubKey(validators[i].PubKey)

		vote := commit.GetVote(int32(i))
		sig := commit.Signatures[i]
		if vote == nil || sig.BlockIDFlag != types.BlockIDFlagCommit {
			signed[i] = false
			continue
		}
		// Commit.Signatures is documented as "in order of address to
		// preserve the bonded ValidatorSet order" -- same order this
		// tool's `validators` slice is in (RecoveryHeaders' doc); sanity
		// check that assumption directly rather than trusting it silently.
		if !bytes.Equal(sig.ValidatorAddress, pub.Address()) {
			return "", fmt.Errorf(
				"validator %d: commit signature address %x does not match expected pubkey address %x -- "+
					"Commit.Signatures/RecoveryHeaders' validators are not index-aligned as assumed",
				i, sig.ValidatorAddress, pub.Address())
		}
		signed[i] = true

		if len(vote.Signature) != 64 {
			return "", fmt.Errorf("validator %d: signature is %d bytes, expected 64", i, len(vote.Signature))
		}
		rx, ry, err := decompressEd25519(vote.Signature[:32])
		if err != nil {
			return "", fmt.Errorf("decompressing validator %d signature R: %w", i, err)
		}
		sigRXs[i] = rx[:]
		sigRYs[i] = ry[:]
		sigSs[i] = vote.Signature[32:64] // s is already little-endian, RFC 8032 5.1.6

		// ps_total/ps_hash ARE legitimately shared across all 7 slots'
		// sign-bytes reconstruction: every honest validator's precommit at
		// a given height votes for the SAME BlockID, hence the same
		// PartSetHeader. timestamp_content is NOT shared -- each signer's
		// own Timestamp value is part of what THEY signed, so it must be
		// captured per-validator and used only to verify that validator's
		// own signature (see BoundaryBlockWitness.timestamp_content's doc
		// in main.nr: a single shared timestamp caps signed_power at one
		// validator's power, permanently short of 2/3 quorum -- reproduced
		// live, not a hypothetical).
		protoVote := vote.ToProto()
		signBytes := types.VoteSignBytes(chainID, protoVote)
		tsContent, err := extractTimestampContent(signBytes, chainID)
		if err != nil {
			return "", fmt.Errorf("validator %d sign-bytes: %w", i, err)
		}
		tsContentBytes[i] = tsContent

		if !haveDummy {
			dummySigRX, dummySigRY, dummySigS = sigRXs[i], sigRYs[i], sigSs[i]
			dummyTsBytes = tsContent
			ps_total = commit.BlockID.PartSetHeader.Total
			psHashBytes = commit.BlockID.PartSetHeader.Hash
			haveDummy = true
		}
	}

	if !haveDummy {
		return "", fmt.Errorf("no validator signed at height %d -- impossible for a real committed block", height)
	}
	// Non-signing slots still need a structurally VALID (on-curve) dummy
	// signature -- ed25519_verify's assert_is_on_curve would trap on a
	// zero/garbage point otherwise. The `signed[i]` gate (main.nr's
	// verify_boundary_block) is what actually excludes these from the
	// quorum sum, not the signature's own validity. A dummy timestamp is
	// harmless too: verify_boundary_block builds each slot's own message
	// from block.timestamp_content[i], but a non-signed slot's message
	// never needs to match a real signature.
	for i := 0; i < numValidators; i++ {
		if !signed[i] {
			sigRXs[i], sigRYs[i], sigSs[i] = dummySigRX, dummySigRY, dummySigS
			tsContentBytes[i] = dummyTsBytes
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "ps_total = \"%d\"\n", ps_total)
	fmt.Fprintf(&b, "ps_hash = [%s]\n", byteArrayToml(psHashBytes))
	fmt.Fprintf(&b, "signed = [%s]\n", boolArrayToml(signed[:]))
	fmt.Fprintf(&b, "sig_r_x = [%s]\n", byteArraysToml(sigRXs[:]))
	fmt.Fprintf(&b, "sig_r_y = [%s]\n", byteArraysToml(sigRYs[:]))
	fmt.Fprintf(&b, "sig_s = [%s]\n", byteArraysToml(sigSs[:]))
	// timestamp_content: [BoundedVec<u8,16>; 7], one per validator (see
	// main.nr's BoundaryBlockWitness.timestamp_content doc for why this is
	// per-validator, not shared) -- TOML array-of-tables, confirmed against
	// a real `nargo execute` run (a bare `[tableName.timestamp_content]`
	// single-table, this function's earlier shared-timestamp shape, would
	// silently attach only the LAST `[[...]]` write to the wrong scope).
	for i := 0; i < numValidators; i++ {
		if len(tsContentBytes[i]) > 16 {
			return "", fmt.Errorf("validator %d timestamp content is %d bytes, exceeds BoundedVec<u8,16>'s max", i, len(tsContentBytes[i]))
		}
		storage := make([]byte, 16)
		copy(storage, tsContentBytes[i])
		fmt.Fprintf(&b, "\n[[%s.timestamp_content]]\n", tableName)
		fmt.Fprintf(&b, "storage = [%s]\n", byteArrayToml(storage))
		fmt.Fprintf(&b, "len = \"%d\"\n", len(tsContentBytes[i]))
	}

	return b.String(), nil
}

// buildValidatorSetToml builds the ValidatorSetWitness table (pubkey_x,
// pubkey_y, power for all numValidators genesis validators, decompressed
// into affine little-endian coordinates -- see decompressEd25519's doc).
func buildValidatorSetToml(validators []*sovereigntytypes.QueryValidatorInfo) (string, error) {
	var pubKeyXs, pubKeyYs [numValidators][]byte
	var powers [numValidators]string
	for i := 0; i < numValidators; i++ {
		x, y, err := decompressEd25519(validators[i].PubKey)
		if err != nil {
			return "", fmt.Errorf("decompressing validator %d pubkey: %w", i, err)
		}
		pubKeyXs[i] = x[:]
		pubKeyYs[i] = y[:]
		powers[i] = fmt.Sprintf("%d", validators[i].Power)
	}
	var b strings.Builder
	fmt.Fprintf(&b, "pubkey_x = [%s]\n", byteArraysToml(pubKeyXs[:]))
	fmt.Fprintf(&b, "pubkey_y = [%s]\n", byteArraysToml(pubKeyYs[:]))
	fmt.Fprintf(&b, "power = [%s]\n", strings.Join(quoteAll(powers[:]), ", "))
	return b.String(), nil
}

// decompressEd25519 recovers the affine (x, y) little-endian byte
// coordinates of a compressed ed25519 point (a raw 32-byte pubkey, or a
// signature's first 32 bytes, the R point), for the Noir circuit's
// Ed25519::from((x, y)) constructor. The circuit re-derives the compressed
// form via compress((x,y)) and asserts it matches known bytes elsewhere
// (validator pubkeys are bound via the SimpleValidator leaf hash; see
// circuit/reanchoring/src/main.nr's ValidatorSetWitness doc), so this
// decompression is never trusted on its own, only required to be
// self-consistent -- ground-truthed against real CometBFT keys earlier this
// session (circuit/reanchoring_sigtest/).
func decompressEd25519(compressed []byte) (xLE, yLE [32]byte, err error) {
	p, err := edwards25519.NewIdentityPoint().SetBytes(compressed)
	if err != nil {
		return xLE, yLE, err
	}
	X, Y, Z, _ := p.ExtendedCoordinates()
	zInv := new(field.Element).Invert(Z)
	x := new(field.Element).Multiply(X, zInv)
	y := new(field.Element).Multiply(Y, zInv)
	copy(xLE[:], x.Bytes())
	copy(yLE[:], y.Bytes())
	return xLE, yLE, nil
}

// extractTimestampContent walks a real types.VoteSignBytes(chainID, vote)
// output (round==0 CanonicalVote, MarshalDelimited protobuf) tag-by-tag to
// pull out exactly the Timestamp submessage's own content bytes -- ground-
// truthed field layout (circuit/reanchoring_sigtest/'s
// build_vote_sign_bytes_matches_real_cometbft_output test, earlier this
// session): outer varint length prefix, field1 type (2 bytes, fixed value),
// field2 height (9 bytes, fixed64), field4 block_id (tag+varint-len+content,
// skipped), field5 timestamp (tag+varint-len+CAPTURED content), field6
// chain_id (tag+varint-len+content, cross-checked against chainID as a
// self-verification that this walk landed correctly). Returns an error
// (rather than silently misparsing) if round!=0 produced an unexpected tag,
// or if the trailing chain_id bytes don't match chainID exactly.
func extractTimestampContent(signBytes []byte, chainID string) ([]byte, error) {
	pos := 0
	// outer varint length prefix
	_, n, err := readVarint(signBytes, pos)
	if err != nil {
		return nil, fmt.Errorf("outer length prefix: %w", err)
	}
	pos = n

	// field 1: type, tag 0x08, varint value (1 byte for Precommit=2)
	if pos+2 > len(signBytes) || signBytes[pos] != 0x08 {
		return nil, fmt.Errorf("expected field1(type) tag 0x08 at offset %d, got %#x", pos, signBytes[pos])
	}
	pos += 2

	// field 2: height, tag 0x11, fixed64 (8 bytes)
	if pos+9 > len(signBytes) || signBytes[pos] != 0x11 {
		return nil, fmt.Errorf("expected field2(height) tag 0x11 at offset %d, got %#x", pos, signBytes[pos])
	}
	pos += 9

	// field 4: block_id, tag 0x22 (length-delimited). A 0x19 here would
	// mean field3(round) is present, i.e. round != 0 -- the unsupported case
	// (caller already checked commit.Round==0, so this is a consistency
	// check, not the primary guard).
	if pos >= len(signBytes) || signBytes[pos] != 0x22 {
		return nil, fmt.Errorf("expected field4(block_id) tag 0x22 at offset %d, got %#x (round!=0?)", pos, signBytes[pos])
	}
	pos++
	blockIDLen, n, err := readVarint(signBytes, pos)
	if err != nil {
		return nil, fmt.Errorf("block_id length: %w", err)
	}
	pos = n + int(blockIDLen)

	// field 5: timestamp, tag 0x2a (length-delimited) -- capture content.
	if pos >= len(signBytes) || signBytes[pos] != 0x2a {
		return nil, fmt.Errorf("expected field5(timestamp) tag 0x2a at offset %d, got %#x", pos, signBytes[pos])
	}
	pos++
	tsLen, n, err := readVarint(signBytes, pos)
	if err != nil {
		return nil, fmt.Errorf("timestamp length: %w", err)
	}
	pos = n
	if pos+int(tsLen) > len(signBytes) {
		return nil, fmt.Errorf("timestamp content length %d overruns sign-bytes", tsLen)
	}
	tsContent := signBytes[pos : pos+int(tsLen)]
	pos += int(tsLen)

	// field 6: chain_id, tag 0x32 (length-delimited) -- self-check.
	if pos >= len(signBytes) || signBytes[pos] != 0x32 {
		return nil, fmt.Errorf("expected field6(chain_id) tag 0x32 at offset %d, got %#x", pos, signBytes[pos])
	}
	pos++
	cidLen, n, err := readVarint(signBytes, pos)
	if err != nil {
		return nil, fmt.Errorf("chain_id length: %w", err)
	}
	pos = n
	if pos+int(cidLen) > len(signBytes) {
		return nil, fmt.Errorf("chain_id length %d overruns sign-bytes", cidLen)
	}
	gotChainID := string(signBytes[pos : pos+int(cidLen)])
	if gotChainID != chainID {
		return nil, fmt.Errorf("parsed chain_id %q != expected %q -- byte walk landed incorrectly", gotChainID, chainID)
	}
	pos += int(cidLen)
	if pos != len(signBytes) {
		return nil, fmt.Errorf("%d trailing bytes after chain_id -- byte walk incomplete", len(signBytes)-pos)
	}

	return tsContent, nil
}

// readVarint reads a protobuf base-128 varint starting at signBytes[pos],
// returning (value, new_pos).
func readVarint(b []byte, pos int) (uint64, int, error) {
	var v uint64
	for shift := 0; ; shift += 7 {
		if pos >= len(b) {
			return 0, 0, fmt.Errorf("varint runs past end of buffer")
		}
		if shift >= 64 {
			return 0, 0, fmt.Errorf("varint too long")
		}
		c := b[pos]
		pos++
		v |= uint64(c&0x7f) << shift
		if c&0x80 == 0 {
			break
		}
	}
	return v, pos, nil
}

// fieldDecimal renders a reduce_to_field'd 32-byte value as the decimal
// string Prover.toml expects for a Field-typed parameter -- matching this
// script's existing rt_last/rt_new convention (reanchor_cli.go's
// queryRecoveryHeadersCmd, via math/big), not a new format.
func fieldDecimal(reduced []byte) string {
	return new(big.Int).SetBytes(reduced).String()
}

func boolArrayToml(bs []bool) string {
	parts := make([]string, len(bs))
	for i, b := range bs {
		parts[i] = fmt.Sprintf("%v", b)
	}
	return strings.Join(parts, ", ")
}

// byteArrayToml renders a byte slice as a Noir/TOML `[u8; N]` array literal
// (quoted per-byte hex strings, matching timestamp_content.storage's existing
// convention) -- nargo's Prover.toml parser rejects a single hex string for
// a whole array-typed field ("cannot parse value String(...) into Array"),
// confirmed via a real `nargo execute` run; only Field-typed params accept
// the hex-string shorthand.
func byteArrayToml(b []byte) string {
	parts := make([]string, len(b))
	for i, v := range b {
		parts[i] = fmt.Sprintf("0x%02x", v)
	}
	return strings.Join(quoteAll(parts), ", ")
}

// byteArraysToml renders a slice of byte slices as a `[[u8; N]; M]` array
// literal (e.g. pubkey_x/sig_r_x's per-validator coordinates).
func byteArraysToml(bs [][]byte) string {
	parts := make([]string, len(bs))
	for i, b := range bs {
		parts[i] = "[" + byteArrayToml(b) + "]"
	}
	return strings.Join(parts, ", ")
}

func quoteAll(ss []string) []string {
	out := make([]string, len(ss))
	for i, s := range ss {
		out[i] = fmt.Sprintf("%q", s)
	}
	return out
}
